function removeDiv(raw,id){
 const start=raw.indexOf('<div id="'+id+'"');if(start<0)throw Error("Missing added node "+id);
 const line=raw.lastIndexOf("\n",start);if(raw.slice(line+1,start).trim())throw Error("Nonindent prefix "+id);
 const re=/<\/?div\b[^>]*>/g;re.lastIndex=start;let depth=0,end=-1,m;
 while((m=re.exec(raw))){depth+=m[0].startsWith("</")?-1:1;if(depth===0){end=re.lastIndex;break;}}
 if(end<0)throw Error("Unbalanced added node "+id);
 return raw.slice(0,line)+raw.slice(end);
}
